/*
 * Pico 2 W — WiFi Scan
 * Scans for nearby WiFi networks
 * Uses the onboard CYW43439 wireless chip
 */

#include <WiFi.h>

void setup() {
  Serial.begin(115200);
  delay(1000);

  Serial.println("\n=== Pico 2 W WiFi Scanner ===");
  Serial.println("Initializing WiFi...");

  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);

  Serial.println("Scan starting...\n");
}

void loop() {
  int n = WiFi.scanNetworks();

  if (n == 0) {
    Serial.println("No networks found.");
  } else {
    Serial.print(n);
    Serial.println(" network(s) found:\n");
    for (int i = 0; i < n; i++) {
      Serial.print("  ");
      Serial.print(i + 1);
      Serial.print(". ");
      Serial.print(WiFi.SSID(i));
      Serial.print("  (RSSI: ");
      Serial.print(WiFi.RSSI(i));
      Serial.print(" dBm)  Channel: ");
      Serial.print(WiFi.channel(i));
      Serial.print("  Encryption: ");
      Serial.println(WiFi.encryptionType(i) == WIFI_AUTH_OPEN ? "Open" : "Secured");
    }
  }

  Serial.println("\n--- Scan complete. Next scan in 10s ---\n");
  WiFi.scanDelete();
  delay(10000);
}
